// @ts-expect-error The OpenNext Worker is generated by npm run cf:build.
import handler from "./.open-next/worker.js";
import { secureRequest, secureResponse } from "./lib/response-security";

export default {
  async fetch(request: Request, env: CloudflareEnv, ctx: ExecutionContext) {
    const security = secureRequest(request);
    if (security.redirect) return security.redirect;
    const response = await handler.fetch(security.request, env, ctx);
    return secureResponse(response, security.csp);
  },
} satisfies ExportedHandler<CloudflareEnv>;

// @ts-expect-error These exports may be generated by the adapter for its cache bindings.
export { DOQueueHandler, DOShardedTagCache } from "./.open-next/worker.js";
